import{_ as l,a0 as c,w as d,s as p,I as i,x as a,a1 as t,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"10 個例子教你學會 ncat (nc) 命令 | LCTT x X-CMD","titleTemplate":false,"description":"10 個例子教你學會 ncat (nc) 命令 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 個例子教你學會 ncat (nc) 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 個例子教你學會 ncat (nc) 命令 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171206 10 useful ncat (nc) Command Examples for Linux Systems","title":"10 個例子教你學會 ncat (nc) 命令","tag":"201712","desc":""},"relativePath":"201712/20171206 10 useful ncat (nc) Command Examples for Linux Systems.md","filePath":"[post].md"}'),h={name:"201712/20171206 10 useful ncat (nc) Command Examples for Linux Systems.md"};function r(g,s,k,b,u,f){const e=c("Link");return d(),p("div",null,[s[14]||(s[14]=i("h1",{id:"_10-個例子教你學會-ncat-nc-命令",tabindex:"-1"},[a("10 個例子教你學會 ncat (nc) 命令 "),i("a",{class:"header-anchor",href:"#_10-個例子教你學會-ncat-nc-命令","aria-label":"Permalink to “10 個例子教你學會 ncat (nc) 命令”"},"​")],-1)),i("p",null,[t(e,{href:"https://www.linuxtechi.com/wp-content/uploads/2017/12/nc-ncat-command-examples-Linux-Systems.jpg"},{default:n(()=>[...s[0]||(s[0]=[i("img",{src:"https://www.linuxtechi.com/wp-content/uploads/2017/12/nc-ncat-command-examples-Linux-Systems.jpg",alt:"nc-ncat-command-examples-Linux-Systems"},null,-1)])]),_:1})]),s[15]||(s[15]=o(`<p><code>ncat</code> 或者説 <code>nc</code> 是一款功能類似 <code>cat</code> 的工具，但是是用於網絡的。它是一款擁有多種功能的 CLI 工具，可以用來在網絡上讀、寫以及重定向數據。 它被設計成可以被腳本或其他程序調用的可靠的後端工具。同時由於它能創建任意所需的連接，因此也是一個很好的網絡調試工具。</p><p><code>ncat</code>/<code>nc</code> 既是一個端口掃描工具，也是一款安全工具，還能是一款監測工具，甚至可以做為一個簡單的 TCP 代理。 由於有這麼多的功能，它被譽為是網絡界的瑞士軍刀。 這是每個系統管理員都應該知道並且掌握它。</p><p>在大多數 Debian 發行版中，<code>nc</code> 是默認可用的，它會在安裝系統的過程中自動被安裝。 但是在 CentOS 7 / RHEL 7 的最小化安裝中，<code>nc</code> 並不會默認被安裝。 你需要用下列命令手工安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# yum install nmap-ncat -y</span></span></code></pre></div><p>系統管理員可以用它來審計系統安全，用它來找出開放的端口然後保護這些端口。 管理員還能用它作為客户端來審計 Web 服務器、telnet 服務器、郵件服務器等， 通過 <code>nc</code> 我們可以控制發送的每個字符，也可以查看對方的回應。</p><p>我們還可以用它捕獲客户端發送的數據以此來了解這些客户端是做什麼的。</p><p>在本文中，我們會通過 10 個例子來學習如何使用 <code>nc</code> 命令。</p><h3 id="例子-1-監聽入站連接" tabindex="-1">例子： 1) 監聽入站連接 <a class="header-anchor" href="#例子-1-監聽入站連接" aria-label="Permalink to “例子： 1) 監聽入站連接”">​</a></h3><p>通過 <code>-l</code> 選項，<code>ncat</code> 可以進入監聽模式，使我們可以在指定端口監聽入站連接。 完整的命令是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l port_number</span></span></code></pre></div><p>比如，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 8080</span></span></code></pre></div><p>服務器就會開始在 8080 端口監聽入站連接。</p><h3 id="例子-2-連接遠程系統" tabindex="-1">例子： 2) 連接遠程系統 <a class="header-anchor" href="#例子-2-連接遠程系統" aria-label="Permalink to “例子： 2) 連接遠程系統”">​</a></h3><p>使用下面命令可以用 <code>nc</code> 來連接遠程系統，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat IP_address port_number</span></span></code></pre></div><p>讓我們來看個例子，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 80</span></span></code></pre></div><p>這會創建一個連接，連接到 IP 為 192.168.1.100 的服務器上的 80 端口，然後我們就可以向服務器發送指令了。 比如我們可以輸入下面內容來獲取完整的網頁內容</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET / HTTP/1.1</span></span></code></pre></div><p>或者獲取頁面名稱，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET / HTTP/1.1</span></span></code></pre></div><p>或者我們可以通過以下方式獲得操作系統指紋標識，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HEAD / HTTP/1.1</span></span></code></pre></div><p>這會告訴我們使用的是什麼軟件來運行這個 web 服務器的。</p><h3 id="例子-3-連接-udp-端口" tabindex="-1">例子： 3) 連接 UDP 端口 <a class="header-anchor" href="#例子-3-連接-udp-端口" aria-label="Permalink to “例子： 3) 連接 UDP 端口”">​</a></h3><p>默認情況下，<code>nc</code> 創建連接時只會連接 TCP 端口。 不過我們可以使用 <code>-u</code> 選項來連接到 UDP 端口，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l -u 1234</span></span></code></pre></div><p>現在我們的系統會開始監聽 UDP 的 1234 端口，我們可以使用下面的 <code>netstat</code> 命令來驗證這一點，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ netstat -tunlp | grep 1234</span></span>
<span class="line"><span>udp           0          0 0.0.0.0:1234                 0.0.0.0:*               17341/nc</span></span>
<span class="line"><span>udp6          0          0 :::1234                      :::*                    17341/nc</span></span></code></pre></div><p>假設我們想發送或者説測試某個遠程主機 UDP 端口的連通性，我們可以使用下面命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -v -u {host-ip} {udp-port}</span></span></code></pre></div><p>比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@localhost ~]# ncat -v -u 192.168.105.150 53</span></span>
<span class="line"><span>Ncat: Version 6.40 ( http://nmap.org/ncat )</span></span>
<span class="line"><span>Ncat: Connected to 192.168.105.150:53。</span></span></code></pre></div><h3 id="例子-4-將-nc-作為聊天工具" tabindex="-1">例子： 4) 將 <code>nc</code> 作為聊天工具 <a class="header-anchor" href="#例子-4-將-nc-作為聊天工具" aria-label="Permalink to “例子： 4) 將 nc 作為聊天工具”">​</a></h3><p><code>nc</code> 也可以作為聊天工具來用，我們可以配置服務器監聽某個端口，然後從遠程主機上連接到服務器的這個端口，就可以開始發送消息了。 在服務器這端運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 8080</span></span></code></pre></div><p>在遠程客户端主機上運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 8080</span></span></code></pre></div><p>之後開始發送消息，這些消息會在服務器終端上顯示出來。</p><h3 id="例子-5-將-nc-作為代理" tabindex="-1">例子： 5) 將 <code>nc</code> 作為代理 <a class="header-anchor" href="#例子-5-將-nc-作為代理" aria-label="Permalink to “例子： 5) 將 nc 作為代理”">​</a></h3><p><code>nc</code> 也可以用來做代理。比如下面這個例子，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 8080 | ncat 192.168.1.200 80</span></span></code></pre></div><p>所有發往我們服務器 8080 端口的連接都會自動轉發到 192.168.1.200 上的 80 端口。 不過由於我們使用了管道，數據只能被單向傳輸。 要同時能夠接受返回的數據，我們需要創建一個雙向管道。 使用下面命令可以做到這點:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkfifo 2way</span></span>
<span class="line"><span>$ ncat -l 8080 0&lt;2way | ncat 192.168.1.200 80 1&gt;2way</span></span></code></pre></div><p>現在你可以通過 <code>nc</code> 代理來收發數據了。</p><h3 id="例子-6-使用-nc-拷貝文件" tabindex="-1">例子： 6) 使用 <code>nc</code> 拷貝文件 <a class="header-anchor" href="#例子-6-使用-nc-拷貝文件" aria-label="Permalink to “例子： 6) 使用 nc 拷貝文件”">​</a></h3><p><code>nc</code> 還能用來在系統間拷貝文件，雖然這麼做並不推薦，因為絕大多數系統默認都安裝了 <code>ssh</code>/<code>scp</code>。 不過如果你恰好遇見個沒有 <code>ssh</code>/<code>scp</code> 的系統的話， 你可以用 <code>nc</code> 來作最後的努力。</p><p>在要接受數據的機器上啓動 <code>nc</code> 並讓它進入監聽模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l  8080 &gt; file.txt</span></span></code></pre></div><p>現在去要被拷貝數據的機器上運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 8080 --send-only &lt; data.txt</span></span></code></pre></div><p>這裏，<code>data.txt</code> 是要發送的文件。 <code>-–send-only</code> 選項會在文件拷貝完後立即關閉連接。 如果不加該選項， 我們需要手工按下 <code>ctrl+c</code> 來關閉連接。</p><p>我們也可以用這種方法拷貝整個磁盤分區，不過請一定要小心。</p><h3 id="例子-7-通過-nc-創建後門" tabindex="-1">例子： 7) 通過 <code>nc</code> 創建後門 <a class="header-anchor" href="#例子-7-通過-nc-創建後門" aria-label="Permalink to “例子： 7) 通過 nc 創建後門”">​</a></h3><p><code>nc</code> 命令還可以用來在系統中創建後門，並且這種技術也確實被黑客大量使用。 為了保護我們的系統，我們需要知道它是怎麼做的。 創建後門的命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 10000 -e /bin/bash</span></span></code></pre></div><p><code>-e</code> 標誌將一個 bash 與端口 10000 相連。現在客户端只要連接到服務器上的 10000 端口就能通過 bash 獲取我們系統的完整訪問權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 10000</span></span></code></pre></div><h3 id="例子-8-通過-nc-進行端口轉發" tabindex="-1">例子： 8) 通過 <code>nc</code> 進行端口轉發 <a class="header-anchor" href="#例子-8-通過-nc-進行端口轉發" aria-label="Permalink to “例子： 8) 通過 nc 進行端口轉發”">​</a></h3><p>我們通過選項 <code>-c</code> 來用 <code>nc</code> 進行端口轉發，實現端口轉發的語法為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -u -l  80 -c  &#39;ncat -u -l 8080&#39;</span></span></code></pre></div><p>這樣，所有連接到 80 端口的連接都會轉發到 8080 端口。</p><h3 id="例子-9-設置連接超時" tabindex="-1">例子： 9) 設置連接超時 <a class="header-anchor" href="#例子-9-設置連接超時" aria-label="Permalink to “例子： 9) 設置連接超時”">​</a></h3><p><code>nc</code> 的監聽模式會一直運行，直到手工終止。 不過我們可以通過選項 <code>-w</code> 設置超時時間:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -w 10 192.168.1.100 8080</span></span></code></pre></div><p>這回導致連接 10 秒後終止，不過這個選項只能用於客户端而不是服務端。</p><h3 id="例子-10-使用-k-選項強制-nc-待命" tabindex="-1">例子： 10) 使用 <code>-k</code> 選項強制 <code>nc</code> 待命 <a class="header-anchor" href="#例子-10-使用-k-選項強制-nc-待命" aria-label="Permalink to “例子： 10) 使用 -k 選項強制 nc 待命”">​</a></h3><p>當客户端從服務端斷開連接後，過一段時間服務端也會停止監聽。 但通過選項 <code>-k</code> 我們可以強制服務器保持連接並繼續監聽端口。 命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l -k 8080</span></span></code></pre></div><p>現在即使來自客户端的連接斷了也依然會處於待命狀態。</p><p>自此我們的教程就完了，如有疑問，請在下方留言。</p><hr>`,73)),i("p",null,[s[2]||(s[2]=a("via: ",-1)),t(e,{href:"https://www.linuxtechi.com/nc-ncat-command-examples-linux-systems/"},{default:n(()=>[...s[1]||(s[1]=[a("https://www.linuxtechi.com/nc-ncat-command-examples-linux-systems/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),t(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[3]||(s[3]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 譯者：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[10]||(s[10]=[a("Linux中國",-1)])]),_:1}),s[13]||(s[13]=a(" 榮譽推出",-1))])])}const C=l(h,[["render",r]]);export{x as __pageData,C as default};
